import{roadRoute}from'./road-route.mjs';
export function distance(a,b){const r=Math.PI/180,p=(b[0]-a[0])*r,l=(b[1]-a[1])*r,s=Math.sin(p/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(l/2)**2;return 6371000*2*Math.atan2(Math.sqrt(s),Math.sqrt(Math.max(0,1-s)));}
export function validate(e){const keys=['timestamp','status','latitude','longitude','confidence'];if(Object.keys(e).some(k=>!keys.includes(k)))throw Error('Unexpected field');if(!Number.isFinite(Date.parse(e.timestamp))||!['matched','unmatched','low_confidence'].includes(e.status))throw Error('Invalid event');if(e.confidence!==null&&(!Number.isFinite(e.confidence)||e.confidence<0||e.confidence>1))throw Error('Invalid confidence');if(e.status==='matched'&&(!Number.isFinite(e.latitude)||Math.abs(e.latitude)>90||!Number.isFinite(e.longitude)||Math.abs(e.longitude)>180))throw Error('Invalid position');return e;}
export function reduce(s,e){validate(e);if(s.event&&Date.parse(e.timestamp)<=Date.parse(s.event.timestamp))return s;if(e.status!=='matched')return {...s,event:e,gap:true};const point=[e.latitude,e.longitude],segments=s.segments.map(x=>x.slice());if(s.gap||!segments.length)segments.push([point]);else segments.at(-1).push(point);return{event:e,target:point,matchedTime:e.timestamp,segments,gap:false};}
export const initial=()=>({event:null,target:null,segments:[],gap:false});
export const anchors=roadRoute;
export const cumulative=[0];for(let i=1;i<anchors.length;i++)cumulative.push(cumulative[i-1]+distance(anchors[i-1],anchors[i]));
export const routeLength=cumulative.at(-1),speedMps=10,totalSeconds=routeLength/speedMps;
export function pointAt(seconds){const meters=Math.max(0,Math.min(routeLength,seconds*speedMps));if(meters>=routeLength)return [...anchors.at(-1)];let i=1;while(cumulative[i]<meters)i++;const len=cumulative[i]-cumulative[i-1],f=len?(meters-cumulative[i-1])/len:0;return anchors[i-1].map((v,k)=>v+(anchors[i][k]-v)*f);}
export function roadSlice(startSeconds,endSeconds){const a=Math.max(0,Math.min(routeLength,startSeconds*speedMps)),b=Math.max(a,Math.min(routeLength,endSeconds*speedMps));return [pointAt(a/speedMps),...anchors.filter((p,i)=>cumulative[i]>a&&cumulative[i]<b),pointAt(b/speedMps)];}
export function makeFeed(){let tick=0,timer=null;const lastTick=Math.ceil(totalSeconds*10);return{start(fn,done){if(timer)return;timer=setInterval(()=>{const n=Math.min(totalSeconds,tick/10),p=pointAt(n),status=n>=48&&n<56?'low_confidence':n>=98&&n<104?'unmatched':'matched';fn({timestamp:new Date().toISOString(),status,latitude:status==='matched'?p[0]:null,longitude:status==='matched'?p[1]:null,confidence:status==='matched'?0.88+Math.sin(n/7)*.06:status==='low_confidence'?.32:null},n);tick++;if(tick>lastTick){clearInterval(timer);timer=null;done();}},100);},pause(){clearInterval(timer);timer=null;},reset(){clearInterval(timer);timer=null;tick=0;},get completed(){return tick>lastTick;}};}
